arguments.new_str:
namespace Warehouse;

public sealed class InventoryTracker
{
    private readonly Dictionary<string, Dictionary<string, int>> _warehouseStock = new();
    private readonly Dictionary<string, int> _reorderThresholds = new();
    private const string DefaultWarehouse = "main";

    public void SetReorderThreshold(string sku, int threshold)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        if (threshold < 0)
            throw new ArgumentOutOfRangeException(nameof(threshold), "Threshold cannot be negative.");

        _reorderThresholds[sku] = threshold;
    }

    public int GetReorderThreshold(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        return _reorderThresholds.TryGetValue(sku, out var threshold) ? threshold : 0;
    }

    public int GetStockLevel(string sku) => GetStockLevel(sku, DefaultWarehouse);

    public int GetStockLevel(string sku, string warehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouse);

        return _warehouseStock.TryGetValue(warehouse, out var stock)
            && stock.TryGetValue(sku, out var qty)
            ? qty
            : 0;
    }

    public int GetTotalStockLevel(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        return _warehouseStock.Values
            .Sum(stock => stock.TryGetValue(sku, out var qty) ? qty : 0);
    }

    public void AddStock(string sku, int quantity) => AddStock(sku, quantity, DefaultWarehouse);

    public void AddStock(string sku, int quantity, string warehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");

        if (!_warehouseStock.TryGetValue(warehouse, out var stock))
        {
            stock = new Dictionary<string, int>();
            _warehouseStock[warehouse] = stock;
        }

        stock[sku] = stock.TryGetValue(sku, out var current) ? current + quantity : quantity;
    }

    public void RemoveStock(string sku, int quantity) => RemoveStock(sku, quantity, DefaultWarehouse);

    public void RemoveStock(string sku, int quantity, string warehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");

        var current = GetStockLevel(sku, warehouse);
        if (quantity > current)
            throw new InvalidOperationException(
                $"Insufficient stock for '{sku}' in warehouse '{warehouse}'. Available: {current}, requested: {quantity}.");

        _warehouseStock[warehouse][sku] = current - quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        var total = GetTotalStockLevel(sku);
        var threshold = GetReorderThreshold(sku);
        return total <= threshold;
    }

    public void TransferStock(string sku, int quantity, string fromWarehouse, string toWarehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(fromWarehouse);
        ArgumentException.ThrowIfNullOrWhiteSpace(toWarehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");
        if (string.Equals(fromWarehouse, toWarehouse, StringComparison.Ordinal))
            throw new ArgumentException("Source and destination warehouses must differ.");

        RemoveStock(sku, quantity, fromWarehouse);
        AddStock(sku, quantity, toWarehouse);
    }
}

