using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    // ───────────── Stock Level Basics ─────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));
    }

    [TestMethod]
    public void AddStock_ThenGetStockLevel_ReturnsAddedQuantity()
    {
        _tracker.AddStock("SKU-1", 50);
        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_CalledTwice_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-1", 30);
        _tracker.AddStock("SKU-1", 20);
        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_DifferentSkus_TrackedIndependently()
    {
        _tracker.AddStock("A", 10);
        _tracker.AddStock("B", 25);

        Assert.AreEqual(10, _tracker.GetStockLevel("A"));
        Assert.AreEqual(25, _tracker.GetStockLevel("B"));
    }

    // ───────────── RemoveStock ─────────────

    [TestMethod]
    public void RemoveStock_ReducesStockLevel()
    {
        _tracker.AddStock("SKU-1", 100);
        _tracker.RemoveStock("SKU-1", 40);
        Assert.AreEqual(60, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_EntireQuantity_LeavesZero()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.RemoveStock("SKU-1", 10);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_ExceedsAvailable_ThrowsInvalidOperation()
    {
        _tracker.AddStock("SKU-1", 5);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 10));
    }

    [TestMethod]
    public void RemoveStock_NoStock_ThrowsInvalidOperation()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 1));
    }

    // ───────────── Input Validation ─────────────

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddStock_InvalidSku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(sku!, 1));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddStock_NonPositiveQuantity_ThrowsArgumentOutOfRange(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-1", qty));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void RemoveStock_NonPositiveQuantity_ThrowsArgumentOutOfRange(int qty)
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-1", qty));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }

    // ───────────── Reorder Alerts ─────────────

    [TestMethod]
    public void NeedsReorder_NoThresholdSet_StockAtZero_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-1", 20);
        _tracker.AddStock("SKU-1", 10);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-1", 20);
        _tracker.AddStock("SKU-1", 20);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.SetReorderThreshold("SKU-1", 20);
        _tracker.AddStock("SKU-1", 21);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeValue_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-1", -1));
    }

    [TestMethod]
    public void GetReorderThreshold_NotSet_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetReorderThreshold("SKU-1"));
    }

    [TestMethod]
    public void SetReorderThreshold_UpdatesExistingValue()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.SetReorderThreshold("SKU-1", 30);
        Assert.AreEqual(30, _tracker.GetReorderThreshold("SKU-1"));
    }

    // ───────────── Multi-Warehouse Stock ─────────────

    [TestMethod]
    public void AddStock_DifferentWarehouses_TrackedSeparately()
    {
        _tracker.AddStock("SKU-1", 10, "east");
        _tracker.AddStock("SKU-1", 25, "west");

        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-1", "east"));
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-1", "west"));
    }

    [TestMethod]
    public void GetTotalStockLevel_SumsAcrossWarehouses()
    {
        _tracker.AddStock("SKU-1", 10, "east");
        _tracker.AddStock("SKU-1", 20, "west");
        _tracker.AddStock("SKU-1", 5, "central");

        Assert.AreEqual(35, _tracker.GetTotalStockLevel("SKU-1"));
    }

    [TestMethod]
    public void GetTotalStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetTotalStockLevel("NOPE"));
    }

    [TestMethod]
    public void DefaultWarehouse_UsedWhenNoneSpecified()
    {
        _tracker.AddStock("SKU-1", 15);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-1", "main"));
    }

    // ───────────── Warehouse Transfers ─────────────

    [TestMethod]
    public void TransferStock_MovesQuantityBetweenWarehouses()
    {
        _tracker.AddStock("SKU-1", 50, "east");
        _tracker.TransferStock("SKU-1", 20, "east", "west");

        Assert.AreEqual(30, _tracker.GetStockLevel("SKU-1", "east"));
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-1", "west"));
    }

    [TestMethod]
    public void TransferStock_PreservesTotalStock()
    {
        _tracker.AddStock("SKU-1", 100, "east");
        _tracker.TransferStock("SKU-1", 40, "east", "west");

        Assert.AreEqual(100, _tracker.GetTotalStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferStock_InsufficientSource_Throws()
    {
        _tracker.AddStock("SKU-1", 5, "east");
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-1", 10, "east", "west"));
    }

    [TestMethod]
    public void TransferStock_SameWarehouse_Throws()
    {
        _tracker.AddStock("SKU-1", 10, "east");
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.TransferStock("SKU-1", 5, "east", "east"));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-3)]
    public void TransferStock_NonPositiveQuantity_Throws(int qty)
    {
        _tracker.AddStock("SKU-1", 10, "east");
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.TransferStock("SKU-1", qty, "east", "west"));
    }

    [TestMethod]
    public void TransferStock_FailedTransfer_DoesNotAlterSource()
    {
        _tracker.AddStock("SKU-1", 5, "east");

        try { _tracker.TransferStock("SKU-1", 10, "east", "west"); }
        catch (InvalidOperationException) { /* expected */ }

        Assert.AreEqual(5, _tracker.GetStockLevel("SKU-1", "east"));
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1", "west"));
    }

    // ───────────── Reorder with Multi-Warehouse ─────────────

    [TestMethod]
    public void NeedsReorder_ConsidersTotalAcrossWarehouses()
    {
        _tracker.SetReorderThreshold("SKU-1", 30);
        _tracker.AddStock("SKU-1", 20, "east");
        _tracker.AddStock("SKU-1", 20, "west");

        // Total is 40, threshold is 30
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_AfterTransfer_StillCorrect()
    {
        _tracker.SetReorderThreshold("SKU-1", 30);
        _tracker.AddStock("SKU-1", 40, "east");

        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));

        _tracker.RemoveStock("SKU-1", 15, "east");

        // Total is now 25, threshold is 30
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }
}

